class Solution {
public:
    double findMaxAverage(vector<int>& nums, int k) {
        long long windowSum = 0;
        for (int i = 0; i < k; ++i) {
            windowSum += nums[i];
        }

        long long bestSum = windowSum;

        for (int i = k; i < (int)nums.size(); ++i) {
            windowSum += nums[i] - nums[i - k];
            bestSum = max(bestSum, windowSum);
        }

        return (double)bestSum / k;
    }
};

