    size_t pos = 0;
    int bracketDepth = 0;
    bool inFirstArray = false;

    while (pos < input.size()) {
        if (input[pos] == '[') {
            ++bracketDepth;
            if (bracketDepth == 2) inFirstArray = true;
            ++pos;
        } else if (input[pos] == ']') {
            if (bracketDepth == 2) inFirstArray = false;
            --bracketDepth;
            ++pos;
        } else if (isdigit((unsigned char)input[pos]) || input[pos] == '-') {
            int sign = 1;
            if (input[pos] == '-') {
                sign = -1;
                ++pos;
            }
            int value = 0;
            while (pos < input.size() && isdigit((unsigned char)input[pos])) {
                value = value * 10 + (input[pos] - '0');
                ++pos;
            }
            if (inFirstArray) {
                nums.push_back(sign * value);
            }
        } else {
            ++pos;
        }
    }

    size_t comma = input.rfind(',');
    int k = stoi(input.substr(comma + 1));

    Solution sol;
    cout << setprecision(15) << sol.findMaxAverage(nums, k) << '\n';
